import sys

def morganAndString(a, b):
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        if a[i:] < b[j:]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return ''.join(result)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        a = data[index]
        b = data[index + 1]
        index += 2
        results.append(morganAndString(a, b))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
